import openpyxl
from openpyxl.styles import Font, Alignment

FN = 'sales_data.xlsx'
wb = openpyxl.load_workbook(FN)
ws = wb.active

headers = {}
for cell in ws[1]:
    if cell.value is not None:
        headers[str(cell.value).strip().lower()] = cell.column

def find(*names):
    for name in names:
        for h, col in headers.items():
            if name in h:
                return col
    return None

revenue_col = find('revenue', 'sales', 'total')
profit_col = find('profit', 'net income', 'gross profit', 'income')
cost_col = find('cost', 'cogs', 'expense', 'expenses')

if revenue_col is None:
    raise SystemExit('Could not locate revenue column')
if profit_col is None and cost_col is None:
    raise SystemExit('Could not locate profit or cost column')

new_col = ws.max_column + 1
header_cell = ws.cell(row=1, column=new_col, value='Profit Margin (%)')
header_cell.font = Font(bold=True)
header_cell.alignment = Alignment(horizontal='center')

for r in range(2, ws.max_row + 1):
    rev = ws.cell(row=r, column=revenue_col)
    if rev.value is None:
        continue
    if profit_col is not None:
        num = ws.cell(row=r, column=profit_col).coordinate
    else:
        num = f'({rev.coordinate}-{ws.cell(row=r, column=cost_col).coordinate})'
    cell = ws.cell(row=r, column=new_col, value=f'=IFERROR({num}/{rev.coordinate},"")')
    cell.number_format = '0.0%'

wb.save(FN)
print('done: added Profit Margin (%) column', new_col)

import zipfile, re
import xml.etree.ElementTree as ET

FN = 'sales_data.xlsx'
MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
REL = 'http://schemas.openxmlformats.org/package/2006/relationships'
DOCREL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
ET.register_namespace('', MAIN)
ET.register_namespace('r', DOCREL)

def col_letter(n):
    s = ''
    while n > 0:
        n, rem = divmod(n - 1, 26)
        s = chr(65 + rem) + s
    return s

def col_index(letters):
    n = 0
    for ch in letters.upper():
        n = n * 26 + ord(ch) - 64
    return n

with zipfile.ZipFile(FN) as z:
    names = z.namelist()
    data = {n: z.read(n) for n in names}

wbxml = ET.fromstring(data['xl/workbook.xml'])
rels = ET.fromstring(data['xl/_rels/workbook.xml.rels'])
rid2target = {}
for rel in rels:
    if rel.get('Type', '').endswith('/worksheet'):
        rid2target[rel.get('Id')] = rel.get('Target')

def sheet_path(name, rid):
    t = rid2target.get(rid, '')
    return t.lstrip('/') if t.startswith('/') else ('xl/' + t)

sheets = [(s.get('name'), s.get('{%s}id' % DOCREL)) for s in wbxml.find('{%s}sheets' % MAIN)]
target = None
for name, rid in sheets:
    if 'sales' in (name or '').lower() or 'data' in (name or '').lower():
        target = sheet_path(name, rid)
        break
if target is None:
    target = sheet_path(sheets[0][0], sheets[0][1])

shared = []
if 'xl/sharedStrings.xml' in data:
    sst = ET.fromstring(data['xl/sharedStrings.xml'])
    for si in sst:
        shared.append(''.join(t.text or '' for t in si.iter('{%s}t' % MAIN)))

sheet = ET.fromstring(data[target])
sd = sheet.find('{%s}sheetData' % MAIN)
rows = list(sd)

def cell_val(c):
    t = c.get('t')
    v = c.find('{%s}v' % MAIN)
    if t == 's' and v is not None:
        return shared[int(v.text)]
    if t == 'inlineStr':
        is_ = c.find('{%s}is' % MAIN)
        return ''.join(x.text or '' for x in is_.iter('{%s}t' % MAIN)) if is_ is not None else None
    return v.text if v is not None else None

headers = {}
max_col = max_row = 0
for row in rows:
    r = int(row.get('r', 0))
    max_row = max(max_row, r)
    for c in row:
        ref = c.get('r')
        if not ref:
            continue
        m = re.match(r'([A-Z]+)(\d+)', ref)
        ci = col_index(m.group(1))
        max_col = max(max_col, ci)
        if r == 1:
            val = cell_val(c)
            if val is not None:
                headers[str(val).strip().lower()] = ci

def find(*names):
    for name in names:
        for h, ci in headers.items():
            if name in h:
                return ci
    return None

revenue_col = find('revenue', 'sales', 'total')
profit_col = find('profit', 'net income', 'gross profit', 'income')
cost_col = find('cost', 'cogs', 'expense', 'expenses')
if revenue_col is None or (profit_col is None and cost_col is None):
    raise SystemExit('Could not locate revenue/profit/cost columns in headers: %r' % headers)

new_col = max_col + 1
new_letter = col_letter(new_col)
style_idx = None

if 'xl/styles.xml' in data:
    try:
        styles = ET.fromstring(data['xl/styles.xml'])
        numfmts = styles.find('{%s}numFmts' % MAIN)
        if numfmts is None:
            numfmts = ET.Element('{%s}numFmts' % MAIN)
            styles.insert(0, numfmts)
        ids = [int(nf.get('numFmtId')) for nf in numfmts]
        nid = max(ids + [163]) + 1
        nf = ET.SubElement(numfmts, '{%s}numFmt' % MAIN)
        nf.set('numFmtId', str(nid))
        nf.set('formatCode', '0.0%')
        numfmts.set('count', str(len(numfmts)))
        cellxfs = styles.find('{%s}cellXfs' % MAIN)
        if cellxfs is not None and len(cellxfs):
            base = cellxfs[0]
            xf = ET.SubElement(cellxfs, '{%s}xf' % MAIN)
            for k, v in base.attrib.items():
                if k != 'numFmtId':
                    xf.set(k, v)
            xf.set('numFmtId', str(nid))
            xf.set('applyNumberFormat', '1')
            cellxfs.set('count', str(len(cellxfs)))
            style_idx = len(cellxfs) - 1
        data['xl/styles.xml'] = ET.tostring(styles, xml_declaration=True, encoding='UTF-8')
    except Exception as e:
        print('style warning:', e)

rowmap = {int(row.get('r', 0)): row for row in rows}
if 1 in rowmap:
    hrow = rowmap[1]
else:
    hrow = ET.Element('{%s}row' % MAIN)
    hrow.set('r', '1')
    sd.insert(0, hrow)

def add_cell(row, ref, formula=None, inline=None, s=None):
    c = ET.SubElement(row, '{%s}c' % MAIN)
    c.set('r', ref)
    if s is not None:
        c.set('s', str(s))
    if inline is not None:
        c.set('t', 'inlineStr')
        is_ = ET.SubElement(c, '{%s}is' % MAIN)
        t = ET.SubElement(is_, '{%s}t' % MAIN)
        t.text = inline
    if formula is not None:
        f = ET.SubElement(c, '{%s}f' % MAIN)
        f.text = formula
    return c

add_cell(hrow, new_letter + '1', inline='Profit Margin (%)')

rev_letter = col_letter(revenue_col)
for r in range(2, max_row + 1):
    row = rowmap.get(r)
    if row is None:
        continue
    rev_ref = rev_letter + str(r)
    if not any(c.get('r') == rev_ref for c in row):
        continue
    if profit_col is not None:
        num = col_letter(profit_col) + str(r)
    else:
        num = '(%s-%s)' % (rev_ref, col_letter(cost_col) + str(r))
    add_cell(row, new_letter + str(r), formula='IFERROR(%s/%s,"")' % (num, rev_ref), s=style_idx)

def cell_col(c):
    m = re.match(r'([A-Z]+)', c.get('r') or 'A')
    return col_index(m.group(1))

for row in sd:
    row[:] = sorted(row, key=cell_col)
sd[:] = sorted(sd, key=lambda e: int(e.get('r', 0)))

dim = sheet.find('{%s}dimension' % MAIN)
if dim is not None:
    dim.set('ref', 'A1:%s%d' % (new_letter, max(max_row, 1)))

data[target] = ET.tostring(sheet, xml_declaration=True, encoding='UTF-8')

with zipfile.ZipFile(FN, 'w', zipfile.ZIP_DEFLATED) as z:
    for n in names:
        z.writestr(n, data[n])

print('done: added Profit Margin (%) column %s (revenue=%s, profit/cost=%s/%s, rows=%d)'
      % (new_letter, rev_letter, col_letter(profit_col) if profit_col else '-',
         col_letter(cost_col) if cost_col else '-', max_row))

