    if profit_col is not None:
        num = col_letter(profit_col) + str(r)
    else:
        num = '(%s-%s)' % (rev_ref, col_letter(cost_col) + str(r))
    add_cell(row, new_letter + str(r), formula='IFERROR(%s/%s,"")' % (num, rev_ref), s=style_idx)

def cell_col(c):
    m = re.match(r'([A-Z]+)', c.get('r') or 'A')
    return col_index(m.group(1))

for row in sd:
    row[:] = sorted(row, key=cell_col)
sd[:] = sorted(sd, key=lambda e: int(e.get('r', 0)))

dim = sheet.find('{%s}dimension' % MAIN)
if dim is not None:
    dim.set('ref', 'A1:%s%d' % (new_letter, max(max_row, 1)))

data[target] = ET.tostring(sheet, xml_declaration=True, encoding='UTF-8')

with zipfile.ZipFile(FN, 'w', zipfile.ZIP_DEFLATED) as z:
    for n in names:
        z.writestr(n, data[n])

print(f'done: added Profit Margin (%) column {new_letter} (revenue={rev_letter}, '
      f'profit/cost={col_letter(profit_col) if profit_col else "-"}/'
      f'{col_letter(cost_col) if cost_col else "-"}, rows={max_row})')
